const text = $json.text ?? '';

// Finds a real section heading that stands alone on its line.
// This avoids matching the same headings in the table of contents.
function findHeading(pattern, startAt = 0) {
  const searchText = text.slice(startAt);
  const regex = new RegExp(`^${pattern}\\s*$`, 'm');
  const match = regex.exec(searchText);

  if (!match) return -1;

  return startAt + match.index;
}

function extractSection(startPattern, endPattern) {
  const start = findHeading(startPattern);

  if (start === -1) {
    return null;
  }

  const startLineEnd = text.indexOf('\n', start);
  const contentStart =
    startLineEnd === -1 ? start : startLineEnd + 1;

  const end = endPattern
    ? findHeading(endPattern, contentStart)
    : text.length;

  return text
    .slice(
      contentStart,
      end === -1 ? text.length : end
    )
    .trim();
}

const sections = {
  introduction: extractSection(
    '1\\. Introduction',
    '2\\. Data on medicinal use'
  ),

  medicinal_use: extractSection(
    '2\\. Data on medicinal use',
    '3\\. Non-Clinical Data'
  ),

  nonclinical_data: extractSection(
    '3\\. Non-Clinical Data',
    '4\\. Clinical Data'
  ),

  clinical_data: extractSection(
    '4\\. Clinical Data',
    '5\\. Clinical Safety\\/Pharmacovigilance'
  ),

  clinical_safety: extractSection(
    '5\\. Clinical Safety\\/Pharmacovigilance',
    '6\\. Overall conclusions'
  ),

  overall_conclusions: extractSection(
    '6\\. Overall conclusions',
    'Annex'
  )
};

return {
  json: {
    document_metadata: {
      title: $json.info?.Title ?? null,
      author: $json.info?.Author ?? null,
      document_id:
        $json.info?.Custom?.DM_DocRefId ?? null,
      pages: $json.numpages ?? null
    },

    section_lengths: Object.fromEntries(
      Object.entries(sections).map(([key, value]) => [
        key,
        value?.length ?? 0
      ])
    ),

    sections
  }
};

const metadata = $json.document_metadata ?? {};
const sections = $json.sections ?? {};

function extractBetween(text, startMarker, endMarker = null) {
  if (!text) return null;

  const start = text.indexOf(startMarker);

  if (start === -1) {
    return null;
  }

  const contentStart = start + startMarker.length;

  const end = endMarker
    ? text.indexOf(endMarker, contentStart)
    : text.length;

  return text
    .slice(
      contentStart,
      end === -1 ? text.length : end
    )
    .trim();
}

const introduction = sections.introduction ?? '';
const medicinalUse = sections.medicinal_use ?? '';
const clinicalData = sections.clinical_data ?? '';
const clinicalSafety = sections.clinical_safety ?? '';
const overallConclusions = sections.overall_conclusions ?? '';

const chunks = {

  identity_and_preparations: extractBetween(
    introduction,
    '1.1. Description of the herbal substance(s), herbal preparation(s) or\ncombinations thereof',
    '• Relevant constituents for this assessment report'
  ),

  constituents: extractBetween(
    introduction,
    '• Relevant constituents for this assessment report',
    '1.2. Search and assessment methodology'
  ),

  medicinal_use_conclusion: extractBetween(
    medicinalUse,
    '2.3. Overall conclusions on medicinal use'
  ),

  clinical_efficacy_conclusion: extractBetween(
    clinicalData,
    '4.4. Overall conclusions on clinical pharmacology and efficacy'
  ),

  contraindications: extractBetween(
    clinicalSafety,
    '5.5.2. Contraindications',
    '5.5.3. Special warnings and precautions for use'
  ),

  precautions: extractBetween(
    clinicalSafety,
    '5.5.3. Special warnings and precautions for use',
    '5.5.4. Drug interactions and other forms of interaction'
  ),

  interactions: extractBetween(
    clinicalSafety,
    '5.5.4. Drug interactions and other forms of interaction',
    '5.5.5. Fertility, pregnancy and lactation'
  ),

  pregnancy_lactation: extractBetween(
    clinicalSafety,
    '5.5.5. Fertility, pregnancy and lactation',
    '5.5.6. Overdose'
  ),

  clinical_safety_conclusion: extractBetween(
    clinicalSafety,
    '5.6. Overall conclusions on clinical safety'
  ),

  overall_conclusion: overallConclusions.trim()
};

const chunkLengths = Object.fromEntries(
  Object.entries(chunks).map(([key, value]) => [
    key,
    value?.length ?? 0
  ])
);

const missingChunks = Object.entries(chunks)
  .filter(([key, value]) => !value || value.length === 0)
  .map(([key]) => key);

return {
  json: {
    document_metadata: metadata,

    processing: {
      parser: 'phythera_ema_chunker_v1',
      chunks_created: Object.keys(chunks).length,
      missing_chunks: missingChunks
