const context = $('Define Output Schema').item.json;

const rawOutput = $json.text ?? '';

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Clean and parse model output
// --------------------------------------------------

function cleanJsonString(value) {
  return value
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
