// 2. Validate structure against target schema
// --------------------------------------------------

function validateStructure(expected, actual, path = '$') {

  // null in our schema means:
  // scalar value or null is expected
  if (expected === null) {

    if (
      actual !== null &&
      typeof actual === 'object'
    ) {
      errors.push({
        type: 'type_mismatch',
        path,
        expected: 'scalar_or_null',
        actual: Array.isArray(actual) ? 'array' : 'object'
      });
    }

    return;
  }

  // Arrays
  if (Array.isArray(expected)) {

    if (!Array.isArray(actual)) {
      errors.push({
        type: 'type_mismatch',
        path,
        expected: 'array',
        actual: typeof actual
      });
      return;
    }

    // If schema contains an example object,
    // validate every returned item against it
    if (expected.length > 0 && actual.length > 0) {
      actual.forEach((item, index) => {
        validateStructure(
          expected[0],
          item,
          `${path}[${index}]`
        );
      });
    }

    return;
  }

  // Objects
  if (
    typeof expected === 'object' &&
    expected !== null
  ) {

    if (
      typeof actual !== 'object' ||
      actual === null ||
      Array.isArray(actual)
    ) {
      errors.push({
        type: 'type_mismatch',
        path,
        expected: 'object',
        actual:
          actual === null
            ? 'null'
            : Array.isArray(actual)
            ? 'array'
            : typeof actual
      });

      return;
    }

    const expectedKeys = Object.keys(expected);
    const actualKeys = Object.keys(actual);

    // Missing keys
    for (const key of expectedKeys) {
      if (!(key in actual)) {
        errors.push({
          type: 'missing_key',
          path: `${path}.${key}`
        });
      }
    }

    // Unexpected keys
    for (const key of actualKeys) {
      if (!(key in expected)) {
        errors.push({
          type: 'unexpected_key',
          path: `${path}.${key}`
        });
      }
    }

    // Recursively validate expected keys
    for (const key of expectedKeys) {
      if (key in actual) {
        validateStructure(
          expected[key],
          actual[key],
          `${path}.${key}`
        );
      }
    }
  }
}

// --------------------------------------------------
// 3. Scientific / extraction-quality checks
// --------------------------------------------------

function inspectQuotes(value, path = '$') {

  if (Array.isArray(value)) {
    value.forEach((item, index) =>
      inspectQuotes(item, `${path}[${index}]`)
    );
    return;
  }

