    data.pharmacopoeia_monographs ?? [];

  const monographNumbers = new Set(
    monographs
      .map(item => item?.monograph_number)
      .filter(Boolean)
      .map(String)
  );

  const preparations =
    data.preparations ?? [];

  for (const preparation of preparations) {

    const qualityStandard =
      preparation?.quality_standard;

    if (typeof qualityStandard !== 'string') {
      continue;
    }

    const match =
      qualityStandard.match(/monograph\s+(\d+)/i);

    if (
      match &&
      !monographNumbers.has(match[1])
    ) {
      warnings.push({
        type: 'cross_field_inconsistency',
        field: 'pharmacopoeia_monographs',
        detected_monograph: match[1],
        message:
          `Monograph ${match[1]} appears in a preparation but is not listed in pharmacopoeia_monographs.`
      });
    }
  }
}

// --------------------------------------------------
// Run validation
// --------------------------------------------------

if (extractedData !== null) {

  validateStructure(
    context.extraction_config.target_schema,
    extractedData
  );

  inspectQuotes(extractedData);

  checkIdentityConsistency(extractedData);

  const normalizedSource =
    normalizeText(context.text);

  checkQuoteGrounding(
    extractedData,
    normalizedSource
  );
}

/// --------------------------------------------------
// 5. Verify that source quotes are grounded
//    in the supplied EMA text
// --------------------------------------------------

function normalizeText(value) {
  return String(value ?? '')

    // Unicode normalization
    .normalize('NFKC')

    // Remove soft hyphens
    .replace(/\u00AD/g, '')

    // Undo PDF line-break hyphenation
    // Example: "well-\nestablished" → "well-established"
    .replace(/([A-Za-z])-\s*\n\s*([A-Za-z])/g, '$1-$2')

    // Normalize typographic quotes
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")

    // Normalize different dash characters
    .replace(/[‐-‒–—−]/g, '-')

    // Normalize non-breaking spaces
    .replace(/\u00A0/g, ' ')

    // Collapse whitespace
    .replace(/\s+/g, ' ')

    .trim()
    .toLowerCase();
}

function checkQuoteGrounding(
  value,
  normalizedSource,
  path = '$'
) {

  if (Array.isArray(value)) {
    value.forEach((item, index) =>
      checkQuoteGrounding(
        item,
        normalizedSource,
        `${path}[${index}]`
      )
    );
    return;
  }

  if (
    typeof value === 'object' &&
    value !== null
  ) {

    for (const [key, child] of Object.entries(value)) {

      // Individual source_quote fields
      if (
        key === 'source_quote' &&
        typeof child === 'string' &&
        child.trim().length > 0
      ) {

        const normalizedQuote =
          normalizeText(child);

        if (
          !normalizedSource.includes(
            normalizedQuote
          )
        ) {
          errors.push({
            type: 'ungrounded_source_quote',
            path: `${path}.${key}`,
            message:
              'The quoted evidence could not be found verbatim in the supplied source text.'
          });
        }
      }

      // supporting_quotes arrays
      if (
        key === 'supporting_quotes' &&
        Array.isArray(child)
      ) {

        child.forEach((quote, index) => {

          if (
            typeof quote === 'string' &&
            quote.trim().length > 0
          ) {

            const normalizedQuote =
              normalizeText(quote);

            if (
              !normalizedSource.includes(
                normalizedQuote
              )
            ) {
              errors.push({
                type: 'ungrounded_supporting_quote',
                path:
                  `${path}.${key}[${index}]`,
                message:
                  'Supporting quote could not be found verbatim in the supplied source text.'
              });
            }
          }
        });
      }

      checkQuoteGrounding(
        child,
        normalizedSource,
        `${path}.${key}`
      );
    }
  }
}

