function checkQuoteGrounding(
  value,
  normalizedSource,
  path = '$'
) {

  if (Array.isArray(value)) {
    value.forEach((item, index) =>
      checkQuoteGrounding(
        item,
        normalizedSource,
        `${path}[${index}]`
      )
    );
    return;
  }

  if (
    typeof value === 'object' &&
    value !== null
  ) {

    for (const [key, child] of Object.entries(value)) {

      // Individual source_quote fields
      if (
        key === 'source_quote' &&
        typeof child === 'string' &&
        child.trim().length > 0
      ) {

        const normalizedQuote =
          normalizeText(child);

        if (
          !normalizedSource.includes(
            normalizedQuote
          )
        ) {
          errors.push({
            type: 'ungrounded_source_quote',
            path: `${path}.${key}`,
            message:
              'The quoted evidence could not be found verbatim in the supplied source text.'
          });
        }
      }

      // supporting_quotes arrays
      if (
        key === 'supporting_quotes' &&
        Array.isArray(child)
      ) {

        child.forEach((quote, index) => {

          if (
            typeof quote === 'string' &&
            quote.trim().length > 0
          ) {

            const normalizedQuote =
              normalizeText(quote);

            if (
              !normalizedSource.includes(
                normalizedQuote
              )
            ) {
              errors.push({
                type: 'ungrounded_supporting_quote',
                path:
                  `${path}.${key}[${index}]`,
                message:
                  'Supporting quote could not be found verbatim in the supplied source text.'
              });
            }
          }
        });
      }

      checkQuoteGrounding(
        child,
        normalizedSource,
        `${path}.${key}`
      );
    }
  }
}

// --------------------------------------------------
// Determine overall status
// --------------------------------------------------

let validationStatus = 'pass';

if (errors.length > 0) {
  validationStatus = 'fail';
} else if (warnings.length > 0) {
  validationStatus = 'warning';
}

// --------------------------------------------------
// Return real structured JSON
// --------------------------------------------------

return {
  json: {

    document_metadata:
      context.document_metadata,

    task_type:
      context.task_type,

    source_section:
      context.source_section,

    schema_version:
      context.extraction_config.schema_version,

    validation: {
      status: validationStatus,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    },

    extracted_data:
      extractedData
  }
};

const items = $input.all().map(item => item.json);

const expectedTasks = [
  'identity',
  'constituents',
  'medicinal_use',
  'clinical_efficacy',
  'safety',
  'overall_assessment'
];

const byTask = Object.fromEntries(
  items.map(item => [item.task_type, item])
);

// Completeness check
const missingTasks = expectedTasks.filter(
  task => !byTask[task]
);

if (missingTasks.length > 0) {
  throw new Error(
    `Missing extraction tasks: ${missingTasks.join(', ')}`
  );
}

// Refuse assembly if anything still failed
const failedTasks = items
  .filter(item => item.validation?.status === 'fail')
  .map(item => item.task_type);

if (failedTasks.length > 0) {
  throw new Error(
    `Cannot assemble profile. Failed validation: ${failedTasks.join(', ')}`
  );
}

// Original source metadata
const source = $('Define Source').first().json;
const documentMetadata =
  items[0]?.document_metadata ?? {};

return [
  {
    json: {
      profile_metadata: {
        profile_type: 'EMA',
        schema_version: 'phythera_ema_v1',
        extraction_status: 'validated',

        plant: source.plant ?? null,
        indication_context:
          source.indication_context ?? null,

        source_type:
          source.source_type ?? null,

        document_type:
          source.document_type ?? null,

        source_url:
          source.source_url ?? null,

        document_title:
          documentMetadata.title ?? null,

        document_author:
          documentMetadata.author ?? null,

        document_id:
          documentMetadata.document_id ?? null,

        pages:
          documentMetadata.pages ?? null
      },

      identity:
        byTask.identity.extracted_data,

      constituents:
        byTask.constituents.extracted_data,

      medicinal_use:
        byTask.medicinal_use.extracted_data,

      clinical_efficacy:
        byTask.clinical_efficacy.extracted_data,

      safety:
        byTask.safety.extracted_data,

      overall_assessment:
        byTask.overall_assessment.extracted_data,

      validation_summary: {
        tasks_total: items.length,

        passed: items.filter(
          item => item.validation?.status === 'pass'
        ).length,

        warnings: items.filter(
          item => item.validation?.status === 'warning'
        ).length,

        failed: items.filter(
          item => item.validation?.status === 'fail'
        ).length,

        task_status: Object.fromEntries(
          items.map(item => [
            item.task_type,
            item.validation?.status ?? 'unknown'
          ])
        )
      }
    }
  }
];
